const fluencyItems = [["Bueno…","Well…","Connector","Neutral","Buys a moment before an answer; common in Colombia and elsewhere."],["O sea…","I mean…","Extender","Neutral","Reframes or clarifies an idea."],["Pues…","Well / so…","Connector","Colombian common","Its force depends on tone; it can soften a response or move it along."],["Es que…","It’s just that / the thing is…","Extender","Neutral","Introduces an explanation; avoid using it only as an excuse."],["De hecho…","Actually / in fact…","Connector","Neutral","Adds a confirming or contrasting detail."],["¿Sí me entiendes?","You know what I mean?","Check-in","Informal","Checks shared understanding; use sparingly."],["Todo bien","All good / no problem","Slang","Colombian common","Friendly reassurance; suitable among peers and casual service settings."],["Qué pena…","Sorry / excuse me…","Politeness","Colombian common","A versatile Colombian softener before a request, correction, or interruption."],["Pa’","for / to","Connected speech","Informal speech","A spoken shortening of para; recognize it, but write para in formal contexts."],["¿Qué más?","How’s it going?","Greeting","Colombian common","A casual greeting, not usually a request for more information."],["como que / más o menos","Kind of","Connected speech","Informal speech","“Kind of” softens a claim; use precise language in formal settings."],["voy a / voy a ir a","Gonna","Connected speech","Informal speech","“Gonna” is the spoken reduction of going to; recognize it, but write going to formally."]];
